create table public.anexos (id uuid primary key default gen_random_uuid(), tarefa_id uuid references public.tarefas_prazos(id) on delete cascade, intimacao_id uuid references public.intimacoes(id) on delete cascade, caminho text not null, nome_arquivo text not null, tipo_arquivo text, tamanho_bytes bigint, enviado_por uuid references public.advogados(id) on delete set null, criado_em timestamptz not null default now(), constraint anexos_destino_unico check ((tarefa_id is not null) <> (intimacao_id is not null)))